    if (url.startsWith('/')) return String(source.getKey()).replace(/\/$/, '') + url;
    return url;
}
function isPreviewMedia(url, context) {
    const text = normalizeMediaText(`${url} ${context || ''}`).toLowerCase();
    return /preview|trailer|sample|teaser|promo|sprite|thumbnail|thumb|cover|poster|still|seek/.test(text)
        || /(?:^|[\/_-])pv(?:[\/_-]|\.)/.test(text)
