    function collectAssignedMedia(text, context, list) {
        const normalized = normalizeMediaText(text);
        const re = /([a-zA-Z_$][\w$]*)\s*=\s*['"]([^'"]+\.(?:m3u8|mp4)(?:\?[^'"]*)?)['"]/ig;
